//! Closed BQ060: original three fast modes, with current generated TK010 semantics.
use crate::{engine::RuleResult,model::*,rules::*};
use serde::Serialize;
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ060";
pub(crate) const KEY:&str="bq060-fission";
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn region_slot()->TargetSlotSpec{target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)}
pub(crate) fn definition()->Definition{let mut a=ability(KEY,"裂变：选择一项",Timing::Fast,vec![],vec![],vec![],None);a.play_only=true;a.modes=vec![Mode{key:"shield".into(),label:"本方场上核心放置一个护盾".into(),targets:vec![],ops:vec![Op::BQ060Shield]},Mode{key:"contest".into(),label:"进行一次隐秘对抗".into(),targets:vec![],ops:vec![Op::MysticContest{actor_bonus:0}]},Mode{key:"generate".into(),label:"目标地区生成一个触手".into(),targets:vec![region_slot()],ops:vec![Op::BQ060Generate]}];with_abilities(vec![a])}
fn selected()->Vec<AbilitySpec>{let a=definition().abilities.remove(0);let mut all=vec![a.clone()];for m in &a.modes{let mut s=a.clone();s.targets=m.targets.clone();s.ops=m.ops.clone();s.modes.clear();all.push(s);}all}
fn op_related(o:&Op)->bool{matches!(o,Op::BQ060Shield|Op::BQ060Generate)}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq060-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(op_related)}
pub(crate) fn frame_related(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("bq060-")||f.steps.iter().any(|s|op_related(&s.op))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!selected().iter().any(|s|same(s,a)){return Err("裂变须保留原三个快速模式".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("裂变完整定义不可删改或移植".into());}Ok(())}
pub(crate) fn validate_action(c:&Card,a:&Action)->RuleResult<()>{if c.definition!=ID{return Ok(());}if *a==(Action{card_id:a.card_id.clone(),..Action::new("asset")}){return Ok(());}let generate=a.option.as_deref()==Some("generate");if !matches!(a.option.as_deref(),Some("shield"|"contest"|"generate"))||a.ability_id.as_deref().is_some_and(|k|k!=KEY)||*a!=(Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),option:a.option.clone(),region:if generate{a.region}else{None},..Action::new("play")}){return Err("裂变只接受原模式及其地区目标".into());}Ok(())}
impl Game{
 pub(crate) fn validate_bq060_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){return Ok(());}self.validate_resource_frame(f)?;let s=&f.source;let c=&s.card;let Some(a)=selected().into_iter().find(|a|a.modes.is_empty()&&same(&a.ops,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>()))else{return Err("裂变原模式程序损坏".into());};
 if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||c.face_down||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.ability_key!=KEY||f.cursor>1||f.chosen_region!=f.targets.first().and_then(|t|t.id.strip_prefix("region:").and_then(|r|r.parse().ok()))||f.steps.iter().any(|s|s.context!=f.actor)||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||f.targets.len()!=a.targets.len()||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=1&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|id!=&c.id&&self.mystic_instance_number(id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b))){return Err("裂变来源、支付或执行阶段损坏".into());}
 for(t,spec)in f.targets.iter().zip(a.targets){if !same(&t.spec,&spec)||t.region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("裂变原地区目标损坏".into());}}self.mobility_immutable_identity(c)
 }
 pub(crate) fn validate_bq060_play(&self,i:&StackItem)->RuleResult<()>{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(frame_related){let f=i.frame.as_ref().ok_or("裂变实际事务缺帧")?;self.validate_bq060_frame(f)?;if f.source.card.definition!=ID||f.cursor!=0||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("裂变实际事务外壳损坏".into());}}Ok(())}

 pub(crate) fn bq060_action(&self,actor:usize,c:&Card,a:&Action)->RuleResult<()>{validate_action(c,a)?;if c.definition==ID&&a.kind!="asset"&&!self.has_shoggoth(actor){return Err("裂变仅限修格斯秘社".into());}Ok(())}
 pub(crate) fn bq060_step(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_bq060_frame(f)?;if f.cursor!=1{return Err("裂变须经原结算步骤".into());}if self.players[f.actor].eliminated{return Ok(());}match f.steps[0].op{
 Op::BQ060Shield=>{let ids=self.regions.iter().flat_map(|r|&r.cards).filter(|c|!c.face_down&&c.owner==f.actor&&c.controller==f.actor&&self.selected_core_card(c)).map(|c|c.id.clone()).collect::<Vec<_>>();for id in ids{let c=self.board_mut(&id).unwrap();let placement_before = c.shield; let placement_id = c.id.clone(); c.shield=c.shield.checked_add(1).ok_or("护盾溢出")?; self.record_board_marker_write(&placement_id, crate::batch4_markers::MarkerKind::Shield, placement_before);}},
 Op::BQ060Generate=>{let t=&f.targets[0];if !self.valid_bound_target(f.actor,&f.source,t){return Ok(());}let r=t.id.strip_prefix("region:").and_then(|v|v.parse::<usize>().ok()).ok_or("裂变地区目标无效")?;let c=self.make_generated(crate::generated::GeneratedKind::Tentacle,f.actor)?;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,crate::tentacle::ID,&id,false);},_=>return Err("未知裂变步骤".into())}Ok(())}
 pub(crate) fn validate_bq060_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.validate_bq060_frame(f)?;if frame_related(f)&&!seen.insert(f.frame_id.clone()){return Err("裂变同帧重复续体".into());}Ok(())};for i in &self.stack{self.validate_bq060_play(i)?;if let Some(f)=&i.frame{check(f)?;}}for e in &self.effects{match e{Effect::Frame{frame}=>check(frame)?,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("裂变没有触发声明".into()),_=>{}}}for state in self.mystic_states(){check(&state.frame)?;}if self.pending.as_ref().is_some_and(|p|match &p.resolution{ChoiceResolution::Frame{frame,choice}=>frame_related(frame)&&!matches!(choice,FrameChoice::MysticCommit{..}|FrameChoice::MysticReward{..}),ChoiceResolution::Declare{declaration:d,..}=>d.source.card.definition==ID||related(&d.ability),_=>false}){return Err("裂变无普通帧内待选".into());}Ok(())}
}
